import{_ as a,c as e,o as d,a2 as r}from"./chunks/framework.BKNXJ1nb.js";const n=JSON.parse('{"title":"侦测积木","description":"","frontmatter":{},"headers":[],"relativePath":"scratch-book-preview/6.侦测积木.md","filePath":"scratch-book-preview/6.侦测积木.md"}'),o={name:"scratch-book-preview/6.侦测积木.md"};function h(l,t,c,s,b,p){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="侦测积木" tabindex="-1">侦测积木 <a class="header-anchor" href="#侦测积木" aria-label="Permalink to &quot;侦测积木&quot;">​</a></h1><p>侦测积木是浅蓝色的，一共 17 块。它们负责感觉：碰到了什么、鼠标在哪、键按没按、时间走了多久。侦测积木大多返回一个数值，或者一个&quot;是 / 否&quot;的答案——把它们塞进控制积木的条件里，就能做出&quot;碰到边缘就回头&quot;这样的反应。</p><h2 id="_1-碰到-鼠标指针-v" tabindex="-1">1. 碰到 [鼠标指针 v] ? <a class="header-anchor" href="#_1-碰到-鼠标指针-v" aria-label="Permalink to &quot;1. 碰到 [鼠标指针 v] ?&quot;">​</a></h2><pre class="blocks"><code>碰到 [鼠标指针 v] ?</code></pre><p>问&quot;碰到了吗&quot;，回答是或否。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>对象</td><td>下拉：鼠标指针 / 舞台边缘 / 某个角色</td><td>无</td></tr></tbody></table><h2 id="_2-按下鼠标" tabindex="-1">2. 按下鼠标? <a class="header-anchor" href="#_2-按下鼠标" aria-label="Permalink to &quot;2. 按下鼠标?&quot;">​</a></h2><pre class="blocks"><code>按下鼠标?</code></pre><p>鼠标左键正按着吗。</p><p>没有参数。</p><h2 id="_3-按下-空格-v-键" tabindex="-1">3. 按下 [空格 v] 键? <a class="header-anchor" href="#_3-按下-空格-v-键" aria-label="Permalink to &quot;3. 按下 [空格 v] 键?&quot;">​</a></h2><pre class="blocks"><code>按下 [空格 v] 键?</code></pre><p>指定键正按着吗，回答是或否。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>按键</td><td>下拉选键，还支持&quot;任意&quot;</td><td>无</td></tr></tbody></table><h2 id="_4-小猫-v-的-x-坐标-v" tabindex="-1">4. ([小猫 v] 的 [x 坐标 v]) <a class="header-anchor" href="#_4-小猫-v-的-x-坐标-v" aria-label="Permalink to &quot;4. ([小猫 v] 的 [x 坐标 v])&quot;">​</a></h2><pre class="blocks"><code>([小猫 v] 的 [x 坐标 v])</code></pre><p>报告某个角色（或舞台）的横向位置。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>对象</td><td>下拉选角色或舞台</td><td>无</td></tr><tr><td>属性</td><td>x 坐标、y 坐标、方向、造型、大小、音量、背景名等</td><td>视属性</td></tr></tbody></table><h2 id="_5-小猫-v-的-y-坐标-v" tabindex="-1">5. ([小猫 v] 的 [y 坐标 v]) <a class="header-anchor" href="#_5-小猫-v-的-y-坐标-v" aria-label="Permalink to &quot;5. ([小猫 v] 的 [y 坐标 v])&quot;">​</a></h2><pre class="blocks"><code>([小猫 v] 的 [y 坐标 v])</code></pre><p>报告某个角色（或舞台）的纵向位置。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>对象</td><td>下拉选角色或舞台</td><td>无</td></tr><tr><td>属性</td><td>x 坐标、y 坐标、方向、造型、大小、音量、背景名等</td><td>视属性</td></tr></tbody></table><h2 id="_6-到-鼠标指针-v-的距离" tabindex="-1">6. 到 [鼠标指针 v] 的距离 <a class="header-anchor" href="#_6-到-鼠标指针-v-的距离" aria-label="Permalink to &quot;6. 到 [鼠标指针 v] 的距离&quot;">​</a></h2><pre class="blocks"><code>到 [鼠标指针 v] 的距离</code></pre><p>自己到目标的直线距离。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>目标</td><td>下拉选角色 / 鼠标指针 / 舞台边缘</td><td>像素</td></tr></tbody></table><h2 id="_7-询问-你叫什么名字-v-并等待" tabindex="-1">7. 询问 [你叫什么名字？ v] 并等待 <a class="header-anchor" href="#_7-询问-你叫什么名字-v-并等待" aria-label="Permalink to &quot;7. 询问 [你叫什么名字？ v] 并等待&quot;">​</a></h2><pre class="blocks"><code>询问 [你叫什么名字？ v] 并等待</code></pre><p>弹出输入框提问，脚本停住等回答。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>问题</td><td>问什么</td><td>无</td></tr></tbody></table><h2 id="_8-回答" tabindex="-1">8. 回答 <a class="header-anchor" href="#_8-回答" aria-label="Permalink to &quot;8. 回答&quot;">​</a></h2><pre class="blocks"><code>回答</code></pre><p>上一次询问得到的回答。</p><p>没有参数。</p><h2 id="_9-颜色-红色-v-碰到-蓝色-v" tabindex="-1">9. 颜色 [红色 v] 碰到 [蓝色 v] ? <a class="header-anchor" href="#_9-颜色-红色-v-碰到-蓝色-v" aria-label="Permalink to &quot;9. 颜色 [红色 v] 碰到 [蓝色 v] ?&quot;">​</a></h2><pre class="blocks"><code>颜色 [红色 v] 碰到 [蓝色 v] ?</code></pre><p>自己身上的颜色 A，是否正压在颜色 B 上。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>颜色 A</td><td>自己身上的颜色，用取色器选</td><td>无</td></tr><tr><td>颜色 B</td><td>舞台上的另一种颜色，用取色器选</td><td>无</td></tr></tbody></table><h2 id="_10-计时器" tabindex="-1">10. 计时器 <a class="header-anchor" href="#_10-计时器" aria-label="Permalink to &quot;10. 计时器&quot;">​</a></h2><pre class="blocks"><code>计时器</code></pre><p>从上次归零起过了多少秒。</p><p>没有参数。</p><h2 id="_11-计时器归零" tabindex="-1">11. 计时器归零 <a class="header-anchor" href="#_11-计时器归零" aria-label="Permalink to &quot;11. 计时器归零&quot;">​</a></h2><pre class="blocks"><code>计时器归零</code></pre><p>把计时器清成 0，重新开始数。</p><p>没有参数。</p><h2 id="_12-响度" tabindex="-1">12. 响度 <a class="header-anchor" href="#_12-响度" aria-label="Permalink to &quot;12. 响度&quot;">​</a></h2><pre class="blocks"><code>响度</code></pre><p>麦克风收到的声音大小，0 ~ 100；没开麦克风就是 0。</p><p>没有参数。</p><h2 id="_13-当前时间的-年-v" tabindex="-1">13. 当前时间的 [年 v] <a class="header-anchor" href="#_13-当前时间的-年-v" aria-label="Permalink to &quot;13. 当前时间的 [年 v]&quot;">​</a></h2><pre class="blocks"><code>当前时间的 [年 v]</code></pre><p>报告现在的年、月、日、星期、时、分或秒。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>项目</td><td>下拉选：年 / 月 / 日 / 星期 / 时 / 分 / 秒</td><td>视项目</td></tr></tbody></table><h2 id="_14-2000年至今的天数" tabindex="-1">14. 2000年至今的天数 <a class="header-anchor" href="#_14-2000年至今的天数" aria-label="Permalink to &quot;14. 2000年至今的天数&quot;">​</a></h2><pre class="blocks"><code>2000年至今的天数</code></pre><p>从 2000 年 1 月 1 日到今天过了多少天。</p><p>没有参数。</p><h2 id="_15-将拖动模式设为-不可拖动-v" tabindex="-1">15. 将拖动模式设为 [不可拖动 v] <a class="header-anchor" href="#_15-将拖动模式设为-不可拖动-v" aria-label="Permalink to &quot;15. 将拖动模式设为 [不可拖动 v]&quot;">​</a></h2><pre class="blocks"><code>将拖动模式设为 [不可拖动 v]</code></pre><p>决定角色能不能被鼠标拖着走。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>模式</td><td>下拉：不可拖动（默认） / 可拖动</td><td>无</td></tr></tbody></table><h2 id="_16-鼠标的x坐标" tabindex="-1">16. 鼠标的x坐标 <a class="header-anchor" href="#_16-鼠标的x坐标" aria-label="Permalink to &quot;16. 鼠标的x坐标&quot;">​</a></h2><pre class="blocks"><code>鼠标的x坐标</code></pre><p>鼠标在舞台上的横向位置，-240 ~ 240。</p><p>没有参数。</p><h2 id="_17-鼠标的y坐标" tabindex="-1">17. 鼠标的y坐标 <a class="header-anchor" href="#_17-鼠标的y坐标" aria-label="Permalink to &quot;17. 鼠标的y坐标&quot;">​</a></h2><pre class="blocks"><code>鼠标的y坐标</code></pre><p>鼠标在舞台上的纵向位置，-180 ~ 180。</p><p>没有参数。</p>',70)])])}const v=a(o,[["render",h]]);export{n as __pageData,v as default};
